contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value, address _target) public payable {
        require(_target != address(0));

        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool revertedWithdrawAll;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedWithdrawAll = true; } else { revertedWithdrawAll = false; }

        bool revertedSendMoney;
        c.sendMoney(_target, _value); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedSendMoney = true; } else { revertedSendMoney = false; }

        assert(c.depositsCount() == beforeDeposits);
    }

    receive() external payable {}
}

